-- GENERATED by gen_mxh3_vault.py -- models are generated, never hand-edited.
--   SAT_CLAIM_FNOL
--   anchor      : HUB_CLAIM
--   grain       : SCD2 (data_7.js sats[].hist)
--   child key   : (none declared)
--   feeders     : 1 -- one per (view, DECLARED ANCHOR EXPRESSION)
--   payload     : 2 attribute(s), NULL-PADDED TO THE SATELLITE
--
--   The child key is the MODEL'S declared key, read from data_7.js
--   sats[].childkey keyed by sats[].code. target.key_name is the HUB key
--   name and is null on all 1,888 satellite rows, so it is never read here.
--
--   The hashdiff is GUARDED against an all-null input: without the guard
--   every all-null row hashes to ONE value and the population collapses.

with feeders as (select * from (
    select
        md5(upper(HUB_CLAIM_BK__K0)) as HUB_CLAIM_HK,
        CLAIM_REASON as PRELIMINARY_LOSS_DESCRIPTION,
        EXPECTED_AMOUNT as PRELIMINARY_LOSS_ESTIMATE,
        'MAXI_HLTH_CLM_VW_DATA_CLAIM_DETAIL_CLAIMDETAIL_ATTRIBUTE_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_clm_cd_clmdetail_apv') }}
    where HUB_CLAIM_K0__EMIT
)), hashed as (select *,
        case when PRELIMINARY_LOSS_DESCRIPTION is not null or PRELIMINARY_LOSS_ESTIMATE is not null
             then md5(upper(coalesce(PRELIMINARY_LOSS_DESCRIPTION::varchar,'') || '||' || coalesce(PRELIMINARY_LOSS_ESTIMATE::varchar,'')))
        end as SAT_CLAIM_FNOL_HASHDIFF
    from feeders)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_FNOL_HASHDIFF is not null
